// Card R1: the engine reads the city, not the home city. What this file pins:
//  - a v5.18 save (home and Boston, generated by the engine before R1: fixtures/saves-v5.18.json) migrates to the same state as it did;
//  - `findHood` is a lookup that misses, `def` is total over the ids a city has and throws on any other;
//  - a city without voice (barks, cast, night-oven lines, founder) is silent or generic, and never speaks in the home city's words.
import '../features';
import * as fs from 'fs';
import * as path from 'path';
import * as G from '../game';
import { CITIES, cityOf, findHood, hoodIds } from '../../content/cities';
import { HOME_CITY } from '../../content/cities/home';
import { HOME_BARKS, HOME_ORDER_CAST } from '../../content/cities/home/voice';
import { BOSTON_CITY } from '../../content/cities/boston';
import { newBarkMem, nextBark, barkText } from '../features/heads';
import { nightOvenView } from '../night-oven';
import { castOf, metHoods } from '../orders';
import { rewardsUnlocked } from '../rewards';
import { stepsFor } from '../tutorial';
import { hireOnSidewalk } from '../../components/sidewalk-model';
import type { CityDef } from '../../content/cities';

const NOW = new Date(2026, 10, 11, 12, 0, 0).getTime();
const LATER = NOW + 5 * 3600_000;
const saves = JSON.parse(fs.readFileSync(path.join(__dirname, 'fixtures/saves-v5.18.json'), 'utf8')) as Record<
  string,
  { save: unknown; migrated: Record<string, any> }
>;

describe('a save from v5.18 migrates to the state it always did', () => {
  test.each(['home', 'boston'])('%s', (name) => {
    const { save, migrated } = saves[name];
    const now = JSON.parse(JSON.stringify(G.migrate(JSON.parse(JSON.stringify(save)), LATER)));
    expect(now).toEqual(migrated);
  });

  test('a new game in each city starts as it did (the same hoods, cash, shops and tutorial)', () => {
    for (const city of Object.values(CITIES)) {
      const g = G.newGame(NOW, city.id);
      expect(Object.keys(g.shops)).toEqual([...hoodIds(city)]);
      expect(g.active).toBe(G.firstHood(city));
      expect(Object.keys((g.x.service as { shops: object }).shops)).toEqual([...hoodIds(city)]);
    }
  });
});

describe('the neighbourhood lookup', () => {
  test('findHood returns undefined for an id no city has', () => {
    expect(findHood('atlantis')).toBeUndefined();
    expect(findHood('atlantis', HOME_CITY)).toBeUndefined();
  });

  test('def throws on an unknown id, with or without a city, and answers every id a city has', () => {
    expect(() => G.def('atlantis')).toThrow(/atlantis/);
    expect(() => G.def('atlantis', HOME_CITY)).toThrow(/atlantis/);
    expect(() => G.def(hoodIds(BOSTON_CITY)[0], HOME_CITY)).toThrow();
    for (const city of Object.values(CITIES)) for (const id of hoodIds(city)) expect(G.def(id).id).toBe(id);
  });
});

describe('a city with no voice is silent or generic, never the home city', () => {
  const quiet: CityDef = { ...BOSTON_CITY, barks: undefined, orderCast: undefined, nightOvenLines: undefined, founder: undefined };
  const homeHood = hoodIds(HOME_CITY)[0];

  test('barks: the home city has lines for every shop, station and trigger; a city without any has silent heads', () => {
    expect(Object.keys(HOME_CITY.barks ?? {})).toEqual([...hoodIds(HOME_CITY)]);
    const asks = [{ trigger: 'rush' as const, station: 'prep' as const }];
    expect(nextBark(newBarkMem(), homeHood, asks, 100, false, HOME_CITY.barks ?? {}).bark?.text).toBe(HOME_BARKS[homeHood].prep.rush);
    const silent = nextBark(newBarkMem(), homeHood, asks, 100, false, quiet.barks ?? {});
    expect(silent.bark).toBeNull();
    expect(silent.mem).toEqual(newBarkMem());
    expect(barkText({}, homeHood, 'prep', 'rush')).toBeUndefined();
  });

  test("orders: a city without a cast asks nobody, and Boston's shops (no cast) do not ask", () => {
    expect(castOf(HOME_CITY, homeHood)).toBe(HOME_ORDER_CAST[homeHood]);
    expect(castOf(quiet, hoodIds(quiet)[0])).toBeUndefined();
    const g = G.newGame(NOW, BOSTON_CITY.id);
    const built = {
      ...g,
      shops: Object.fromEntries(Object.entries(g.shops).map(([id, s]) => [id, { ...s, built: true }])),
      seenScenes: hoodIds(BOSTON_CITY).map((id) => G.sceneId(id, 1)),
    };
    expect(metHoods(built)).toEqual([]);
  });

  test("the night oven's name and line: the city's own, else a generic one without Nonna (Boston has none yet: C152)", () => {
    const home = nightOvenView(G.newGame(NOW));
    expect(home.name).toBe("Nonna's night oven");
    expect(home.body).toBe("While you're away, Nonna's night oven keeps baking for up to 4 h. Come back before it's full!");
    const bostonOven = nightOvenView(G.newGame(NOW, BOSTON_CITY.id));
    expect(bostonOven.body).toContain('up to 4 h');
    expect(bostonOven.name + bostonOven.body).not.toMatch(/Nonna/);
    const bare = { ...BOSTON_CITY, nightOvenLines: undefined };
    CITIES.bare = bare;
    try {
      const v = nightOvenView({ ...G.newGame(NOW, BOSTON_CITY.id), city: 'bare' });
      expect(v.body).toContain('up to 4 h');
      expect(v.body).not.toMatch(/Nonna/);
    } finally {
      delete CITIES.bare;
    }
  });

  test("the founder: the city's own, else its first manager", () => {
    expect(G.founderName(G.newGame(NOW))).toBe('Nonna');
    expect(G.founderName(G.newGame(NOW, BOSTON_CITY.id))).toBe(BOSTON_CITY.managers[G.firstHood(BOSTON_CITY)].name);
  });
});

describe("Boston's own first shop, tutorial and rewards (C152: the v5.18 bugs are gone)", () => {
  const boston = G.newGame(NOW, BOSTON_CITY.id);

  test('rewards stay unlocked by the home takeover scene Boston inherits on franchising (a decision, see boston/index.ts)', () => {
    expect(rewardsUnlocked({ ...boston, seenScenes: [BOSTON_CITY.fit.takeover.sceneId] })).toBe(false);
    expect(rewardsUnlocked({ ...boston, seenScenes: ['downtown-4'] })).toBe(true);
    expect(rewardsUnlocked({ ...G.newGame(NOW), seenScenes: ['downtown-4'] })).toBe(true);
  });

  test('the first shop shows its stations on the sidewalk, in Boston as at home', () => {
    for (const city of [BOSTON_CITY, HOME_CITY]) {
      const first = G.firstHood(city);
      expect(hireOnSidewalk(G.newGame(NOW, city.id).shops[first], first, city)).toBe(false);
      expect(hireOnSidewalk({ managed: false }, hoodIds(city)[1], city)).toBe(true);
    }
  });

  test("the tutorial's hire step names the city's own prep head", () => {
    const text = (c: CityDef) => stepsFor(c)[12].text; // step 13: the prep head's hire card
    expect(text(BOSTON_CITY)).toContain(BOSTON_CITY.heads[G.firstHood(BOSTON_CITY)].prep);
    expect(text(BOSTON_CITY)).not.toContain(HOME_CITY.heads[G.firstHood(HOME_CITY)].prep);
  });
});
